CREATE TABLE IF NOT EXISTS performance_blueprints(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL,agreement_intelligence_version_id UUID NOT NULL REFERENCES agreement_intelligence_versions(id),blueprint_number INTEGER NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,effective_from TIMESTAMPTZ,objectives JSONB NOT NULL,configuration_snapshot_id UUID NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1,content_hash TEXT NOT NULL,UNIQUE(contract_id,blueprint_number));
CREATE TABLE IF NOT EXISTS scope_definitions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),included JSONB NOT NULL,excluded JSONB NOT NULL,assumptions JSONB NOT NULL,constraints JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS blueprint_deliverables(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),deliverable_key TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,owner_id UUID NOT NULL,quantity NUMERIC NOT NULL CHECK(quantity>0),unit TEXT NOT NULL,due_date DATE NOT NULL,acceptance_method TEXT NOT NULL,evidence_requirements JSONB NOT NULL,source_references JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1,UNIQUE(blueprint_id,deliverable_key));
CREATE TABLE IF NOT EXISTS planned_milestones(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),milestone_key TEXT NOT NULL,title TEXT NOT NULL,owner_id UUID NOT NULL,duration_days INTEGER NOT NULL CHECK(duration_days>=0),value_minor BIGINT NOT NULL CHECK(value_minor>=0),currency TEXT NOT NULL,deliverable_ids JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(blueprint_id,milestone_key));
CREATE TABLE IF NOT EXISTS planned_milestone_dependencies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),predecessor_id UUID NOT NULL REFERENCES planned_milestones(id),successor_id UUID NOT NULL REFERENCES planned_milestones(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(predecessor_id<>successor_id),UNIQUE(predecessor_id,successor_id));
CREATE TABLE IF NOT EXISTS blueprint_definitions_of_done(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL REFERENCES performance_blueprints(id),deliverable_id UUID NOT NULL REFERENCES blueprint_deliverables(id),version INTEGER NOT NULL,criteria JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),content_hash TEXT NOT NULL,UNIQUE(deliverable_id,version));
CREATE INDEX IF NOT EXISTS blueprint_contract_status_idx ON performance_blueprints(workspace_id,contract_id,status);CREATE INDEX IF NOT EXISTS blueprint_deliverable_due_idx ON blueprint_deliverables(workspace_id,due_date);CREATE INDEX IF NOT EXISTS planned_milestone_blueprint_idx ON planned_milestones(blueprint_id);
ALTER TABLE performance_blueprints ENABLE ROW LEVEL SECURITY;ALTER TABLE scope_definitions ENABLE ROW LEVEL SECURITY;ALTER TABLE blueprint_deliverables ENABLE ROW LEVEL SECURITY;ALTER TABLE planned_milestones ENABLE ROW LEVEL SECURITY;ALTER TABLE planned_milestone_dependencies ENABLE ROW LEVEL SECURITY;ALTER TABLE blueprint_definitions_of_done ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['performance_blueprints','scope_definitions','blueprint_deliverables','planned_milestones','planned_milestone_dependencies','blueprint_definitions_of_done'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['performance_blueprints','scope_definitions','blueprint_deliverables','planned_milestones','planned_milestone_dependencies','blueprint_definitions_of_done'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
